import { request, requestOrNull, seg, Page, requestFile, ExportRequest } from './apiSupport';
import { QuoteDTO } from './QuoteDTO';
import { QuoteKeyDTO } from './QuoteKeyDTO';
import { QuoteSrchDTO } from './QuoteSrchDTO';
import { QuoteStatus } from './QuoteStatus';

/**
 * REST client for Quote.
 *
 * Calls the endpoints QuoteController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/quote';

/** Registers a new Quote. */
export async function create(input: QuoteDTO, init?: RequestInit): Promise<QuoteDTO> {
    return request<QuoteDTO>('POST', BASE, input, init);
}

/** The Quote with this identifier, or null when there is none. */
export async function findById(quoteId: number, init?: RequestInit): Promise<QuoteDTO | null> {
    return requestOrNull<QuoteDTO>('GET', BASE + '/' + seg(quoteId), init);
}

/** Every Quote matching the condition. */
export async function search(condition: QuoteSrchDTO, init?: RequestInit): Promise<Page<QuoteDTO>> {
    return request<Page<QuoteDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Quote. */
export async function update(input: QuoteDTO, init?: RequestInit): Promise<QuoteDTO> {
    return request<QuoteDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: QuoteDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: QuoteKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Quote with this identifier. */
export async function deleteById(quoteId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(quoteId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportQuote(body: ExportRequest<QuoteSrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

/** Whether send may be given now: the status is DRAFT. */
export function canSend(value: QuoteDTO | null | undefined): boolean {
    return value != null && (value.status === QuoteStatus.DRAFT);
}

/** Whether accept may be given now: the status is SENT. */
export function canAccept(value: QuoteDTO | null | undefined): boolean {
    return value != null && (value.status === QuoteStatus.SENT);
}

/** Whether reject may be given now: the status is SENT. */
export function canReject(value: QuoteDTO | null | undefined): boolean {
    return value != null && (value.status === QuoteStatus.SENT);
}

/** Whether it may be deleted now: the status is DRAFT or REJECTED. */
export function canDelete(value: QuoteDTO | null | undefined): boolean {
    return value != null && (value.status === QuoteStatus.DRAFT || value.status === QuoteStatus.REJECTED);
}

/** The send command: Quote decides, and answers with what it became. */
export async function send(quoteId: number, init?: RequestInit): Promise<QuoteDTO> {
    return request<QuoteDTO>('POST', BASE + '/' + seg(quoteId) + '/send', undefined, init);
}

/** The accept command: Quote decides, and answers with what it became. */
export async function accept(quoteId: number, init?: RequestInit): Promise<QuoteDTO> {
    return request<QuoteDTO>('POST', BASE + '/' + seg(quoteId) + '/accept', undefined, init);
}

/** The reject command: Quote decides, and answers with what it became. */
export async function reject(quoteId: number, init?: RequestInit): Promise<QuoteDTO> {
    return request<QuoteDTO>('POST', BASE + '/' + seg(quoteId) + '/reject', undefined, init);
}

